{"path": "frontend/src/style.css", "content": "/* Reset & Base */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

:root {
  --hour-height: 60px;
  --gutter-width: 60px;
  --header-height: 50px;
  --total-hours: 24;
  --grid-height: calc(var(--hour-height) * var(--total-hours));
  --border-color: #ddd;
  --today-bg: #e8f0fe;
  --event-bg: #4285f4;
  --event-text: #fff;
  --event-border: #3367d6;
}

html, body {
  height: 100%;
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  font-size: 14px;
  color: #333;
  background: #fafafa;
}

#app {
  display: flex;
  flex-direction: column;
  height: 100vh;
}

/* Header */
#calendar-header {
  display: flex;
  align-items: center;
  padding: 12px 16px;
  background: #fff;
  border-bottom: 1px solid var(--border-color);
  gap: 16px;
  flex-shrink: 0;
}

.nav-controls {
  display: flex;
  gap: 4px;
}

.nav-controls button {
  padding: 6px 14px;
  border: 1px solid var(--border-color);
  background: #fff;
  cursor: pointer;
  border-radius: 4px;
  font-size: 13px;
  transition: background 0.15s;
}

.nav-controls button:hover {
  background: #f0f0f0;
}

#week-title {
  font-size: 18px;
  font-weight: 600;
}

/* Calendar Container */
#calendar-container {
  flex: 1;
  overflow-y: auto;
  overflow-x: hidden;
  position: relative;
  display: grid;
  grid-template-columns: var(--gutter-width) 1fr;
  grid-template-rows: var(--header-height) 1fr;
}

/* Day Headers */
#day-headers {
  grid-column: 2;
  grid-row: 1;
  display: grid;
  grid-template-columns: repeat(7, 1fr);
  border-bottom: 1px solid var(--border-color);
  position: sticky;
  top: 0;
  z-index: 10;
  background: #fff;
}

.day-header {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 4px;
  border-left: 1px solid var(--border-color);
  font-size: 12px;
}

.day-header.today {
  background: var(--today-bg);
}

.day-header .day-name {
  text-transform: uppercase;
  color: #70757a;
  font-size: 11px;
  font-weight: 600;
}

.day-header .day-number {
  font-size: 22px;
  font-weight: 500;
  line-height: 1.2;
}

.day-header.today .day-number {
  background: var(--event-bg);
  color: #fff;
  border-radius: 50%;
  width: 32px;
  height: 32px;
  display: flex;
  align-items: center;
  justify-content: center;
}

/* Time Gutter - header spacer */
#time-gutter {
  grid-column: 1;
  grid-row: 1 / 3;
  position: sticky;
  top: 0;
  z-index: 11;
  background: #fff;
}

/* Time labels in gutter */
.time-label {
  position: absolute;
  right: 8px;
  font-size: 11px;
  color: #70757a;
  line-height: 1;
  transform: translateY(-50%);
  pointer-events: none;
}

/* Week Grid */
#week-grid {
  grid-column: 2;
  grid-row: 2;
  display: grid;
  grid-template-columns: repeat(7, 1fr);
  position: relative;
  height: var(--grid-height);
}

.day-column {
  position: relative;
  border-left: 1px solid var(--border-color);
}

.day-column.today {
  background: var(--today-bg);
}

/* Hour lines */
.hour-line {
  position: absolute;
  left: 0;
  right: 0;
  border-top: 1px solid var(--border-color);
  height: 0;
  pointer-events: none;
}

/* Half-hour lines */
.half-hour-line {
  position: absolute;
  left: 0;
  right: 0;
  border-top: 1px dotted #eee;
  height: 0;
  pointer-events: none;
}

/* Event blocks */
.event-block {
  position: absolute;
  background: var(--event-bg);
  color: var(--event-text);
  border: 1px solid var(--event-border);
  border-radius: 4px;
  padding: 2px 4px;
  font-size: 11px;
  overflow: hidden;
  cursor: pointer;
  z-index: 5;
  transition: filter 0.15s;
  line-height: 1.3;
}

.event-block:hover {
  filter: brightness(0.9);
  z-index: 6;
}

.event-block .event-title {
  font-weight: 600;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.event-block .event-time {
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  font-size: 10px;
  opacity: 0.9;
}

/* Modal */
.modal-overlay {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: rgba(0, 0, 0, 0.4);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 100;
}

.modal-overlay.hidden {
  display: none;
}

.modal {
  background: #fff;
  border-radius: 8px;
  padding: 24px;
  width: 400px;
  max-width: 90vw;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.15);
}

.modal h2 {
  margin-bottom: 16px;
  font-size: 18px;
}

.form-group {
  margin-bottom: 12px;
}

.form-group label {
  display: block;
  margin-bottom: 4px;
  font-size: 13px;
  font-weight: 500;
  color: #555;
}

.form-group input {
  width: 100%;
  padding: 8px 10px;
  border: 1px solid var(--border-color);
  border-radius: 4px;
  font-size: 14px;
}

.form-group input:focus {
  outline: none;
  border-color: var(--event-bg);
  box-shadow: 0 0 0 2px rgba(66, 133, 244, 0.2);
}

.form-error {
  color: #d93025;
  font-size: 13px;
  margin-bottom: 12px;
  padding: 6px 10px;
  background: #fce8e6;
  border-radius: 4px;
}

.form-error.hidden {
  display: none;
}

.form-actions {
  display: flex;
  gap: 8px;
  margin-top: 16px;
}

.form-actions button {
  padding: 8px 16px;
  border: 1px solid var(--border-color);
  border-radius: 4px;
  cursor: pointer;
  font-size: 14px;
  transition: background 0.15s;
}

#btn-save {
  background: var(--event-bg);
  color: #fff;
  border-color: var(--event-border);
}

#btn-save:hover {
  background: var(--event-border);
}

.btn-danger {
  background: #d93025;
  color: #fff;
  border-color: #c5221f !important;
}

.btn-danger:hover {
  background: #c5221f;
}

#btn-cancel {
  background: #fff;
}

#btn-cancel:hover {
  background: #f0f0f0;
}

/* Selection highlight for creating events */
.selection-highlight {
  position: absolute;
  background: rgba(66, 133, 244, 0.2);
  border: 1px dashed var(--event-bg);
  border-radius: 4px;
  pointer-events: none;
  z-index: 4;
  left: 0;
  right: 0;
}
"}

{"path": "frontend/src/api.js", "content": "const API_BASE = '/api';

export async function fetchEvents(start, end) {
  const params = new URLSearchParams({
    start: start.toISOString(),
    end: end.toISOString()
  });
  const res = await fetch(`${API_BASE}/events?${params}`);
  if (!res.ok) throw new Error('Failed to fetch events');
  return res.json();
}

export async function createEvent(event) {
  const res = await fetch(`${API_BASE}/events`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(event)
  });
  const data = await res.json();
  if (!res.ok) throw new Error(data.error || 'Failed to create event');
  return data;
}

export async function updateEvent(id, event) {
  const res = await fetch(`${API_BASE}/events/${id}`, {
    method: 'PUT',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(event)
  });
  const data = await res.json();
  if (!res.ok) throw new Error(data.error || 'Failed to update event');
  return data;
}

export async function deleteEvent(id) {
  const res = await fetch(`${API_BASE}/events/${id}`, {
    method: 'DELETE'
  });
  if (!res.ok) {
    const data = await res.json();
    throw new Error(data.error || 'Failed to delete event');
  }
  return true;
}
"}

{"path": "frontend/src/layout.js", "content": "/**
 * Cluster-based overlap layout engine.
 *
 * Given an array of events for a single day, each with minuteStart and minuteEnd
 * (minutes from midnight, 0–1440), compute the layout: column index and total
 * columns in its cluster.
 *
 * Algorithm:
 * 1. Sort events by start time, then by end time descending (so longer events come first).
 * 2. Build maximal overlap clusters: a cluster is a set of events where each event
 *    overlaps at least one other event in the cluster (transitive closure of overlap).
 * 3. Within each cluster, greedily assign columns: iterate events in start-time order;
 *    assign each event the lowest-numbered column that is free at its start time.
 * 4. Each event in a cluster gets width = 1/maxColumns and left = column/maxColumns
 *    (as fractions of the day-column width).
 */

/**
 * @typedef {Object} EventInput
 * @property {number} id
 * @property {string} title
 * @property {number} minuteStart - minutes from midnight (0–1440)
 * @property {number} minuteEnd   - minutes from midnight (0–1440)
 */

/**
 * @typedef {Object} LayoutResult
 * @property {number} id
 * @property {string} title
 * @property {number} minuteStart
 * @property {number} minuteEnd
 * @property {number} column     - 0-based column index within cluster
 * @property {number} totalColumns - total columns in this cluster
 */

/**
 * Compute layout for a list of events on a single day.
 * @param {EventInput[]} events
 * @returns {LayoutResult[]}
 */
export function computeDayLayout(events) {
  if (events.length === 0) return [];

  // Sort by start time, then by longest duration first (descending end)
  const sorted = [...events].sort((a, b) => {
    if (a.minuteStart !== b.minuteStart) return a.minuteStart - b.minuteStart;
    return b.minuteEnd - a.minuteEnd;
  });

  // Build clusters: groups of transitively overlapping events
  const clusters = [];
  let currentCluster = [sorted[0]];
  let clusterEnd = sorted[0].minuteEnd;

  for (let i = 1; i < sorted.length; i++) {
    const ev = sorted[i];
    if (ev.minuteStart < clusterEnd) {
      // Overlaps with the current cluster
      currentCluster.push(ev);
      clusterEnd = Math.max(clusterEnd, ev.minuteEnd);
    } else {
      // No overlap; start a new cluster
      clusters.push(currentCluster);
      currentCluster = [ev];
      clusterEnd = ev.minuteEnd;
    }
  }
  clusters.push(currentCluster);

  // For each cluster, assign columns greedily
  const results = [];

  for (const cluster of clusters) {
    // columns[c] = end time of the last event placed in column c
    const columns = [];

    for (const ev of cluster) {
      let placed = false;
      for (let c = 0; c < columns.length; c++) {
        if (columns[c] <= ev.minuteStart) {
          // This column is free
          columns[c] = ev.minuteEnd;
          ev._column = c;
          placed = true;
          break;
        }
      }
      if (!placed) {
        ev._column = columns.length;
        columns.push(ev.minuteEnd);
      }
    }

    const totalColumns = columns.length;

    for (const ev of cluster) {
      results.push({
        id: ev.id,
        title: ev.title,
        minuteStart: ev.minuteStart,
        minuteEnd: ev.minuteEnd,
        column: ev._column,
        totalColumns,
        // Preserve original event data for click handling
        _event: ev._event || ev
      });
    }
  }

  return results;
}
"}

{"path": "frontend/src/date-utils.js", "content": "/**
 * Date utility functions for calendar navigation.
 * All operations use local time.
 */

const DAY_NAMES = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
const MONTH_NAMES = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 
                     'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];

/**
 * Get the Monday of the week containing the given date.
 * @param {Date} date
 * @returns {Date} Monday at 00:00:00
 */
export function getMonday(date) {
  const d = new Date(date);
  const day = d.getDay(); // 0=Sun, 1=Mon, ...
  const diff = day === 0 ? -6 : 1 - day; // if Sunday, go back 6 days
  d.setDate(d.getDate() + diff);
  d.setHours(0, 0, 0, 0);
  return d;
}

/**
 * Get an array of 7 dates (Mon–Sun) for the week starting at monday.
 * @param {Date} monday
 * @returns {Date[]}
 */
export function getWeekDays(monday) {
  const days = [];
  for (let i = 0; i < 7; i++) {
    const d = new Date(monday);
    d.setDate(monday.getDate() + i);
    days.push(d);
  }
  return days;
}

/**
 * Get the start of the week (Monday 00:00) and the end (next Monday 00:00)
 * for use as the query range.
 */
export function getWeekRange(monday) {
  const start = new Date(monday);
  start.setHours(0, 0, 0, 0);
  const end = new Date(monday);
  end.setDate(end.getDate() + 7);
  end.setHours(0, 0, 0, 0);
  return { start, end };
}

/**
 * Format a date for display: "Mon 12"
 */
export function formatDayHeader(date) {
  return {
    dayName: DAY_NAMES[date.getDay()],
    dayNumber: date.getDate()
  };
}

/**
 * Format week title: "Jan 6 – 12, 2025" or "Dec 30, 2024 – Jan 5, 2025"
 */
export function formatWeekTitle(monday) {
  const sunday = new Date(monday);
  sunday.setDate(monday.getDate() + 6);

  const mMonth = MONTH_NAMES[monday.getMonth()];
  const sMonth = MONTH_NAMES[sunday.getMonth()];

  if (monday.getFullYear() !== sunday.getFullYear()) {
    return `${mMonth} ${monday.getDate()}, ${monday.getFullYear()} – ${sMonth} ${sunday.getDate()}, ${sunday.getFullYear()}`;
  }
  if (monday.getMonth() !== sunday.getMonth()) {
    return `${mMonth} ${monday.getDate()} – ${sMonth} ${sunday.getDate()}, ${sunday.getFullYear()}`;
  }
  return `${mMonth} ${monday.getDate()} – ${sunday.getDate()}, ${sunday.getFullYear()}`;
}

/**
 * Check if two dates are the same calendar day.
 */
export function isSameDay(a, b) {
  return a.getFullYear() === b.getFullYear() &&
         a.getMonth() === b.getMonth() &&
         a.getDate() === b.getDate();
}

/**
 * Format time as HH:MM
 */
export function formatTime(hours, minutes) {
  return `${String(hours).padStart(2, '0')}:${String(minutes).padStart(2, '0')}`;
}

/**
 * Convert a Date to minutes from midnight in local time.
 */
export function minutesFromMidnight(date) {
  return date.getHours() * 60 + date.getMinutes();
}

/**
 * Format as local ISO string for datetime-local input: "YYYY-MM-DDTHH:MM"
 */
export function toLocalISOString(date) {
  const y = date.getFullYear();
  const m = String(date.getMonth() + 1).padStart(2, '0');
  const d = String(date.getDate()).padStart(2, '0');
  const h = String(date.getHours()).padStart(2, '0');
  const min = String(date.getMinutes()).padStart(2, '0');
  return `${y}-${m}-${d}T${h}:${min}`;
}

/**
 * Format as full ISO-like string for API: "YYYY-MM-DDTHH:MM:SS"
 */
export function toAPIDateString(date) {
  const y = date.getFullYear();
  const m = String(date.getMonth() + 1).padStart(2, '0');
  const d = String(date.getDate()).padStart(2, '0');
  const h = String(date.getHours()).padStart(2, '0');
  const min = String(date.getMinutes()).padStart(2, '0');
  const s = String(date.getSeconds()).padStart(2, '0');
  return `${y}-${m}-${d}T${h}:${min}:${s}`;
}
"}

{"path": "frontend/src/main.js", "content": "import { fetchEvents, createEvent, updateEvent, deleteEvent } from './api.js';
import { computeDayLayout } from './layout.js';
import {
  getMonday, getWeekDays, getWeekRange,
  formatDayHeader, formatWeekTitle, isSameDay,
  formatTime, minutesFromMidnight, toLocalISOString, toAPIDateString
} from './date-utils.js';

// Constants
const HOUR_HEIGHT = 60; // px per hour - must match CSS var(--hour-height)
const TOTAL_MINUTES = 24 * 60;
const TOTAL_HEIGHT = 24 * HOUR_HEIGHT;
const HEADER_HEIGHT = 50; // must match CSS var(--header-height)

// State
let currentMonday = getMonday(new Date());
let events = [];
let editingEvent = null; // null = creating, object = editing

// DOM references
const weekTitle = document.getElementById('week-title');
const dayHeaders = document.getElementById('day-headers');
const weekGrid = document.getElementById('week-grid');
const timeGutter = document.getElementById('time-gutter');
const modalOverlay = document.getElementById('modal-overlay');
const modalTitle = document.getElementById('modal-title');
const eventForm = document.getElementById('event-form');
const eventTitleInput = document.getElementById('event-title');
const eventStartInput = document.getElementById('event-start');
const eventEndInput = document.getElementById('event-end');
const formError = document.getElementById('form-error');
const btnSave = document.getElementById('btn-save');
const btnDelete = document.getElementById('btn-delete');
const btnCancel = document.getElementById('btn-cancel');
const btnPrev = document.getElementById('btn-prev');
const btnToday = document.getElementById('btn-today');
const btnNext = document.getElementById('btn-next');

// --- Rendering ---

function renderTimeGutter() {
  timeGutter.innerHTML = '';
  // Position time labels at the gutter column; the first label (00:00) sits at the top of the grid area
  for (let h = 0; h <= 24; h++) {
    const label = document.createElement('div');
    label.className = 'time-label';
    label.textContent = formatTime(h % 24, 0);
    // Position relative to gutter top. The grid area starts after the header.
    label.style.top = `${HEADER_HEIGHT + h * HOUR_HEIGHT}px`;
    timeGutter.appendChild(label);
  }
}

function renderDayHeaders() {
  const days = getWeekDays(currentMonday);
  const today = new Date();
  dayHeaders.innerHTML = '';

  days.forEach(day => {
    const { dayName, dayNumber } = formatDayHeader(day);
    const header = document.createElement('div');
    header.className = 'day-header';
    if (isSameDay(day, today)) {
      header.classList.add('today');
    }

    const nameEl = document.createElement('span');
    nameEl.className = 'day-name';
    nameEl.textContent = dayName;

    const numEl = document.createElement('span');
    numEl.className = 'day-number';
    numEl.textContent = dayNumber;

    header.appendChild(nameEl);
    header.appendChild(numEl);
    dayHeaders.appendChild(header);
  });
}

function renderWeekGrid() {
  const days = getWeekDays(currentMonday);
  const today = new Date();
  weekGrid.innerHTML = '';

  days.forEach((day, dayIndex) => {
    const column = document.createElement('div');
    column.className = 'day-column';
    column.dataset.dayIndex = dayIndex;
    if (isSameDay(day, today)) {
      column.classList.add('today');
    }

    // Hour lines
    for (let h = 0; h < 24; h++) {
      const hourLine = document.createElement('div');
      hourLine.className = 'hour-line';
      hourLine.style.top = `${h * HOUR_HEIGHT}px`;
      column.appendChild(hourLine);

      // Half-hour line
      const halfLine = document.createElement('div');
      halfLine.className = 'half-hour-line';
      halfLine.style.top = `${h * HOUR_HEIGHT + HOUR_HEIGHT / 2}px`;
      column.appendChild(halfLine);
    }

    // Bottom line at 24:00
    const bottomLine = document.createElement('div');
    bottomLine.className = 'hour-line';
    bottomLine.style.top = `${24 * HOUR_HEIGHT}px`;
    column.appendChild(bottomLine);

    // Setup click-drag for creating events
    setupDayColumnInteraction(column, day);

    weekGrid.appendChild(column);
  });

  renderEvents();
}

function renderEvents() {
  const days = getWeekDays(currentMonday);

  // Group events by day
  const eventsByDay = new Map();
  days.forEach((day, i) => eventsByDay.set(i, []));

  events.forEach(ev => {
    const evStart = new Date(ev.start_at);
    const evEnd = new Date(ev.end_at);

