       RETURNING id, title,
                 to_char(start_at, 'YYYY-MM-DD"T"HH24:MI:SS') as start_at,
                 to_char(end_at, 'YYYY-MM-DD"T"HH24:MI:SS') as end_at`,
      [title.trim(), start_at, end_at, id]
    );

    if (result.rows.length === 0) {
