.btn-danger {
  background: #d93025;
  color: #fff;
  border-color: #c5221f !important;
}

.btn-danger:hover {
  background: #c5221f;
}

#btn-cancel {
  background: #fff;
}

#btn-cancel:hover {
  background: #f0f0f0;
}

/* Selection highlight for creating events */
.selection-highlight {
  position: absolute;
  background: rgba(66, 133, 244, 0.2);
  border: 1px dashed var(--event-bg);
  border-radius: 4px;
  pointer-events: none;
  z-index: 4;
  left: 0;
  right: 0;
}
