  z-index: 11;
  background: #fff;
}

/* Time labels in gutter */
.time-label {
  position: absolute;
  right: 8px;
  font-size: 11px;
  color: #70757a;
  line-height: 1;
  transform: translateY(-50%);
  pointer-events: none;
}

/* Week Grid */
#week-grid {
