/* Reset & Base */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

:root {
  --hour-height: 60px;
  --gutter-width: 60px;
  --header-height: 50px;
  --total-hours: 24;
  --grid-height: calc(var(--hour-height) * var(--total-hours));
  --border-color: #ddd;
  --today-bg: #e8f0fe;
  --event-bg: #4285f4;
  --event-text: #fff;
  --event-border: #3367d6;
}

html, body {
  height: 100%;
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  font-size: 14px;
  color: #333;
  background: #fafafa;
}

#app {
  display: flex;
  flex-direction: column;
  height: 100vh;
}

/* Header */
#calendar-header {
  display: flex;
  align-items: center;
  padding: 12px 16px;
  background: #fff;
  border-bottom: 1px solid var(--border-color);
  gap: 16px;
  flex-shrink: 0;
}

.nav-controls {
  display: flex;
  gap: 4px;
}

.nav-controls button {
  padding: 6px 14px;
  border: 1px solid var(--border-color);
  background: #fff;
  cursor: pointer;
  border-radius: 4px;
  font-size: 13px;
  transition: background 0.15s;
}

.nav-controls button:hover {
  background: #f0f0f0;
}

#week-title {
  font-size: 18px;
  font-weight: 600;
}

/* Calendar Container */
#calendar-container {
  flex: 1;
  overflow-y: auto;
  overflow-x: hidden;
  position: relative;
  display: grid;
  grid-template-columns: var(--gutter-width) 1fr;
  grid-template-rows: var(--header-height) 1fr;
}

/* Day Headers */
#day-headers {
  grid-column: 2;
  grid-row: 1;
  display: grid;
  grid-template-columns: repeat(7, 1fr);
  border-bottom: 1px solid var(--border-color);
  position: sticky;
  top: 0;
  z-index: 10;
  background: #fff;
}

.day-header {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 4px;
  border-left: 1px solid var(--border-color);
  font-size: 12px;
}

.day-header.today {
  background: var(--today-bg);
}

.day-header .day-name {
  text-transform: uppercase;
  color: #70757a;
  font-size: 11px;
  font-weight: 600;
}

.day-header .day-number {
  font-size: 22px;
  font-weight: 500;
  line-height: 1.2;
}

.day-header.today .day-number {
  background: var(--event-bg);
  color: #fff;
  border-radius: 50%;
  width: 32px;
  height: 32px;
  display: flex;
  align-items: center;
  justify-content: center;
}

/* Time Gutter - header spacer */
#time-gutter {
  grid-column: 1;
  grid-row: 1 / 3;
  position: sticky;
  top: 0;
  z-index: 11;
  background: #fff;
}

/* Time labels in gutter */
.time-label {
  position: absolute;
  right: 8px;
  font-size: 11px;
  color: #70757a;
  line-height: 1;
  transform: translateY(-50%);
  pointer-events: none;
}

/* Week Grid */
#week-grid {
  grid-column: 2;
  grid-row: 2;
  display: grid;
  grid-template-columns: repeat(7, 1fr);
  position: relative;
  height: var(--grid-height);
}

.day-column {
  position: relative;
  border-left: 1px solid var(--border-color);
}

.day-column.today {
  background: var(--today-bg);
}

/* Hour lines */
.hour-line {
  position: absolute;
  left: 0;
  right: 0;
  border-top: 1px solid var(--border-color);
  height: 0;
  pointer-events: none;
}

/* Half-hour lines */
.half-hour-line {
  position: absolute;
  left: 0;
  right: 0;
  border-top: 1px dotted #eee;
  height: 0;
  pointer-events: none;
}

/* Event blocks */
.event-block {
  position: absolute;
  background: var(--event-bg);
  color: var(--event-text);
  border: 1px solid var(--event-border);
  border-radius: 4px;
  padding: 2px 4px;
  font-size: 11px;
  overflow: hidden;
  cursor: pointer;
  z-index: 5;
  transition: filter 0.15s;
  line-height: 1.3;
}

.event-block:hover {
  filter: brightness(0.9);
  z-index: 6;
}

.event-block .event-title {
  font-weight: 600;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.event-block .event-time {
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  font-size: 10px;
  opacity: 0.9;
}

/* Modal */
.modal-overlay {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: rgba(0, 0, 0, 0.4);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 100;
}

.modal-overlay.hidden {
  display: none;
}

.modal {
  background: #fff;
  border-radius: 8px;
  padding: 24px;
  width: 400px;
  max-width: 90vw;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.15);
}

.modal h2 {
  margin-bottom: 16px;
  font-size: 18px;
}

.form-group {
  margin-bottom: 12px;
}

.form-group label {
  display: block;
  margin-bottom: 4px;
  font-size: 13px;
  font-weight: 500;
  color: #555;
}

.form-group input {
  width: 100%;
  padding: 8px 10px;
  border: 1px solid var(--border-color);
  border-radius: 4px;
  font-size: 14px;
}

.form-group input:focus {
  outline: none;
  border-color: var(--event-bg);
  box-shadow: 0 0 0 2px rgba(66, 133, 244, 0.2);
}

.form-error {
  color: #d93025;
  font-size: 13px;
  margin-bottom: 12px;
  padding: 6px 10px;
  background: #fce8e6;
  border-radius: 4px;
}

.form-error.hidden {
  display: none;
}

.form-actions {
  display: flex;
  gap: 8px;
  margin-top: 16px;
}

.form-actions button {
  padding: 8px 16px;
  border: 1px solid var(--border-color);
  border-radius: 4px;
  cursor: pointer;
  font-size: 14px;
  transition: background 0.15s;
}

#btn-save {
  background: var(--event-bg);
  color: #fff;
  border-color: var(--event-border);
}

#btn-save:hover {
  background: var(--event-border);
}

.btn-danger {
  background: #d93025;
  color: #fff;
  border-color: #c5221f !important;
}

.btn-danger:hover {
  background: #c5221f;
}

#btn-cancel {
  background: #fff;
}

#btn-cancel:hover {
  background: #f0f0f0;
}

/* Selection highlight for creating events */
.selection-highlight {
  position: absolute;
  background: rgba(66, 133, 244, 0.2);
  border: 1px dashed var(--event-bg);
  border-radius: 4px;
  pointer-events: none;
  z-index: 4;
  left: 0;
  right: 0;
}

const express = require('express');
const cors = require('cors');
const path = require('path');
const { PGlite } = require('@electric-sql/pglite');

const app = express();
const PORT = process.env.PORT || 3001;
const DB_PATH = path.join(__dirname, '..', 'pgdata');

app.use(cors());
app.use(express.json());

let db;

async function initDB() {
  db = new PGlite(DB_PATH);

  await db.query(`
    CREATE TABLE IF NOT EXISTS events (
      id SERIAL PRIMARY KEY,
      title TEXT NOT NULL CHECK (title <> ''),
      start_at TIMESTAMP NOT NULL,
      end_at TIMESTAMP NOT NULL,
      CHECK (end_at > start_at)
    );
  `);

  console.log('Database initialized');
}

// GET /api/events?start=<iso>&end=<iso>
// Returns all events overlapping [start, end)
app.get('/api/events', async (req, res) => {
  try {
    const { start, end } = req.query;
    if (!start || !end) {
      return res.status(400).json({ error: 'start and end query parameters are required' });
    }

    const result = await db.query(
      `SELECT id, title,
              to_char(start_at, 'YYYY-MM-DD"T"HH24:MI:SS') as start_at,
              to_char(end_at, 'YYYY-MM-DD"T"HH24:MI:SS') as end_at
       FROM events
       WHERE start_at < $2 AND end_at > $1
       ORDER BY start_at, end_at`,
      [start, end]
    );

    res.json(result.rows);
  } catch (err) {
    console.error('GET /api/events error:', err);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// POST /api/events
app.post('/api/events', async (req, res) => {
  try {
    const { title, start_at, end_at } = req.body;

    // Validate
    if (!title || typeof title !== 'string' || title.trim() === '') {
      return res.status(400).json({ error: 'Title is required and must be non-empty' });
    }
    if (!start_at || !end_at) {
      return res.status(400).json({ error: 'start_at and end_at are required' });
    }

    const startDate = new Date(start_at);
    const endDate = new Date(end_at);

    if (isNaN(startDate.getTime()) || isNaN(endDate.getTime())) {
      return res.status(400).json({ error: 'Invalid date format' });
    }

    if (endDate <= startDate) {
      return res.status(400).json({ error: 'end_at must be after start_at' });
    }

    const result = await db.query(
      `INSERT INTO events (title, start_at, end_at) VALUES ($1, $2, $3)
       RETURNING id, title,
                 to_char(start_at, 'YYYY-MM-DD"T"HH24:MI:SS') as start_at,
                 to_char(end_at, 'YYYY-MM-DD"T"HH24:MI:SS') as end_at`,
      [title.trim(), start_at, end_at]
    );

    res.status(201).json(result.rows[0]);
  } catch (err) {
    console.error('POST /api/events error:', err);
    if (err.message && err.message.includes('violates check constraint')) {
      return res.status(400).json({ error: 'Invalid event data' });
    }
    res.status(500).json({ error: 'Internal server error' });
  }
});

// PUT /api/events/:id
app.put('/api/events/:id', async (req, res) => {
  try {
    const { id } = req.params;
    const { title, start_at, end_at } = req.body;

    if (!title || typeof title !== 'string' || title.trim() === '') {
      return res.status(400).json({ error: 'Title is required and must be non-empty' });
    }
    if (!start_at || !end_at) {
      return res.status(400).json({ error: 'start_at and end_at are required' });
    }

    const startDate = new Date(start_at);
    const endDate = new Date(end_at);

    if (isNaN(startDate.getTime()) || isNaN(endDate.getTime())) {
      return res.status(400).json({ error: 'Invalid date format' });
    }

    if (endDate <= startDate) {
      return res.status(400).json({ error: 'end_at must be after start_at' });
    }

    const result = await db.query(
      `UPDATE events SET title = $1, start_at = $2, end_at = $3 WHERE id = $4
       RETURNING id, title,
                 to_char(start_at, 'YYYY-MM-DD"T"HH24:MI:SS') as start_at,
                 to_char(end_at, 'YYYY-MM-DD"T"HH24:MI:SS') as end_at`,
      [title.trim(), start_at, end_at, id]
    );

    if (result.rows.length === 0) {
      return res.status(404).json({ error: 'Event not found' });
    }

    res.json(result.rows[0]);
  } catch (err) {
    console.error('PUT /api/events error:', err);
    if (err.message && err.message.includes('violates check constraint')) {
      return res.status(400).json({ error: 'Invalid event data' });
    }
    res.status(500).json({ error: 'Internal server error' });
  }
});

// DELETE /api/events/:id
app.delete('/api/events/:id', async (req, res) => {
  try {
    const { id } = req.params;

    const result = await db.query(
      'DELETE FROM events WHERE id = $1 RETURNING id',
      [id]
    );

    if (result.rows.length === 0) {
      return res.status(404).json({ error: 'Event not found' });
    }

    res.json({ success: true });
  } catch (err) {
    console.error('DELETE /api/events error:', err);
    res.status(500).json({ error: 'Internal server error' });
  }
});

async function start() {
  await initDB();
  app.listen(PORT, () => {
    console.log(`Backend server running on http://localhost:${PORT}`);
  });
}

start().catch(err => {
  console.error('Failed to start server:', err);
  process.exit(1);
});

/**
 * Date utility functions for calendar navigation.
 * All operations use local time.
 */

const DAY_NAMES = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
const MONTH_NAMES = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 
                     'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];

/**
 * Get the Monday of the week containing the given date.
 * @param {Date} date
 * @returns {Date} Monday at 00:00:00
 */
export function getMonday(date) {
  const d = new Date(date);
  const day = d.getDay(); // 0=Sun, 1=Mon, ...
  const diff = day === 0 ? -6 : 1 - day; // if Sunday, go back 6 days
  d.setDate(d.getDate() + diff);
  d.setHours(0, 0, 0, 0);
  return d;
}

/**
 * Get an array of 7 dates (Mon–Sun) for the week starting at monday.
 * @param {Date} monday
 * @returns {Date[]}
 */
export function getWeekDays(monday) {
  const days = [];
  for (let i = 0; i < 7; i++) {
    const d = new Date(monday);
    d.setDate(monday.getDate() + i);
    days.push(d);
  }
  return days;
}

/**
 * Get the start of the week (Monday 00:00) and the end (next Monday 00:00)
 * for use as the query range.
 */
export function getWeekRange(monday) {
  const start = new Date(monday);
  start.setHours(0, 0, 0, 0);
  const end = new Date(monday);
  end.setDate(end.getDate() + 7);
  end.setHours(0, 0, 0, 0);
  return { start, end };
}

/**
 * Format a date for display: "Mon 12"
 */
export function formatDayHeader(date) {
  return {
    dayName: DAY_NAMES[date.getDay()],
    dayNumber: date.getDate()
  };
}

/**
 * Format week title: "Jan 6 – 12, 2025" or "Dec 30, 2024 – Jan 5, 2025"
 */
export function formatWeekTitle(monday) {
  const sunday = new Date(monday);
  sunday.setDate(monday.getDate() + 6);

  const mMonth = MONTH_NAMES[monday.getMonth()];
  const sMonth = MONTH_NAMES[sunday.getMonth()];

  if (monday.getFullYear() !== sunday.getFullYear()) {
    return `${mMonth} ${monday.getDate()}, ${monday.getFullYear()} – ${sMonth} ${sunday.getDate()}, ${sunday.getFullYear()}`;
  }
  if (monday.getMonth() !== sunday.getMonth()) {
    return `${mMonth} ${monday.getDate()} – ${sMonth} ${sunday.getDate()}, ${sunday.getFullYear()}`;
  }
  return `${mMonth} ${monday.getDate()} – ${sunday.getDate()}, ${sunday.getFullYear()}`;
}

/**
 * Check if two dates are the same calendar day.
 */
export function isSameDay(a, b) {
  return a.getFullYear() === b.getFullYear() &&
         a.getMonth() === b.getMonth() &&
         a.getDate() === b.getDate();
}

/**
 * Format time as HH:MM
 */
export function formatTime(hours, minutes) {
  return `${String(hours).padStart(2, '0')}:${String(minutes).padStart(2, '0')}`;
}

/**
 * Convert a Date to minutes from midnight in local time.
 */
export function minutesFromMidnight(date) {
  return date.getHours() * 60 + date.getMinutes();
}

/**
 * Format as local ISO string for datetime-local input: "YYYY-MM-DDTHH:MM"
 */
export function toLocalISOString(date) {
  const y = date.getFullYear();
  const m = String(date.getMonth() + 1).padStart(2, '0');
  const d = String(date.getDate()).padStart(2, '0');
  const h = String(date.getHours()).padStart(2, '0');
  const min = String(date.getMinutes()).padStart(2, '0');
  return `${y}-${m}-${d}T${h}:${min}`;
}

/**
 * Format as full ISO-like string for API: "YYYY-MM-DDTHH:MM:SS"
 */
export function toAPIDateString(date) {
  const y = date.getFullYear();
  const m = String(date.getMonth() + 1).padStart(2, '0');
  const d = String(date.getDate()).padStart(2, '0');
  const h = String(date.getHours()).padStart(2, '0');
  const min = String(date.getMinutes()).padStart(2, '0');
  const s = String(date.getSeconds()).padStart(2, '0');
  return `${y}-${m}-${d}T${h}:${min}:${s}`;
}

