import { computeDayLayout } from './frontend/src/layout.js';

function assert(condition, message) {
  if (!condition) {
    console.error('FAIL:', message);
    process.exit(1);
  }
  console.log('PASS:', message);
}

// Test 1: Single event takes full width
{
  const result = computeDayLayout([
    { id: 1, title: 'A', minuteStart: 540, minuteEnd: 600 } // 09:00-10:00
  ]);
  assert(result.length === 1, 'Single event');
  assert(result[0].column === 0, 'Single event in column 0');
  assert(result[0].totalColumns === 1, 'Single event: totalColumns=1 (full width)');
}

// Test 2: Two identical events side by side
{
  const result = computeDayLayout([
    { id: 1, title: 'A', minuteStart: 540, minuteEnd: 600 },
    { id: 2, title: 'B', minuteStart: 540, minuteEnd: 600 }
  ]);
  assert(result.length === 2, 'Two identical events');
  const cols = result.map(r => r.column).sort();
  assert(cols[0] === 0 && cols[1] === 1, 'Two identical: columns 0 and 1');
  assert(result[0].totalColumns === 2, 'Two identical: totalColumns=2');
  assert(result[1].totalColumns === 2, 'Two identical: totalColumns=2');
}

// Test 3: Three identical events
{
  const result = computeDayLayout([
    { id: 1, title: 'A', minuteStart: 540, minuteEnd: 600 },
    { id: 2, title: 'B', minuteStart: 540, minuteEnd: 600 },
    { id: 3, title: 'C', minuteStart: 540, minuteEnd: 600 }
  ]);
  assert(result.length === 3, 'Three identical events');
  const cols = result.map(r => r.column).sort();
  assert(cols[0] === 0 && cols[1] === 1 && cols[2] === 2, 'Three identical: columns 0,1,2');
  assert(result.every(r => r.totalColumns === 3), 'Three identical: totalColumns=3');
}

// Test 4: Non-overlapping events each get full width
{
  const result = computeDayLayout([
    { id: 1, title: 'A', minuteStart: 540, minuteEnd: 600 },  // 09:00-10:00
    { id: 2, title: 'B', minuteStart: 720, minuteEnd: 780 }   // 12:00-13:00
  ]);
  assert(result.length === 2, 'Two non-overlapping');
  assert(result[0].totalColumns === 1, 'First non-overlapping: full width');
  assert(result[1].totalColumns === 1, 'Second non-overlapping: full width');
}

// Test 5: Partial chain: 09:00-11:00, 10:00-12:00, 11:30-13:00
{
  const result = computeDayLayout([
    { id: 1, title: 'A', minuteStart: 540, minuteEnd: 660 },  // 09:00-11:00
    { id: 2, title: 'B', minuteStart: 600, minuteEnd: 720 },  // 10:00-12:00
    { id: 3, title: 'C', minuteStart: 690, minuteEnd: 780 }   // 11:30-13:00
  ]);
  assert(result.length === 3, 'Partial chain: 3 events');
  // All transitively overlap, so they form one cluster
  assert(result.every(r => r.totalColumns === 2), 'Partial chain: totalColumns=2 (greedy assigns only 2 columns since C can reuse A\'s column)');

  // A gets col 0, B gets col 1, C can go in col 0 (A ends at 660, C starts at 690)
  const aRes = result.find(r => r.id === 1);
  const bRes = result.find(r => r.id === 2);
  const cRes = result.find(r => r.id === 3);
  assert(aRes.column === 0, 'A in column 0');
  assert(bRes.column === 1, 'B in column 1');
  assert(cRes.column === 0, 'C in column 0 (reuses A\'s column)');
}

// Test 6: Event after a cluster gets full width
{
  const result = computeDayLayout([
    { id: 1, title: 'A', minuteStart: 540, minuteEnd: 600 },  // 09:00-10:00
    { id: 2, title: 'B', minuteStart: 540, minuteEnd: 600 },  // 09:00-10:00
    { id: 3, title: 'C', minuteStart: 720, minuteEnd: 780 }   // 12:00-13:00
  ]);
  const cRes = result.find(r => r.id === 3);
  assert(cRes.totalColumns === 1, 'Event after cluster: full width');
  assert(cRes.column === 0, 'Event after cluster: column 0');
}

// Test 7: Vertical geometry
{
  // 09:00-10:30 should span 1.5 hours
  const result = computeDayLayout([
    { id: 1, title: 'A', minuteStart: 540, minuteEnd: 630 }
  ]);
  const ev = result[0];
  assert(ev.minuteStart === 540, 'Start at 540 (09:00)');
  assert(ev.minuteEnd === 630, 'End at 630 (10:30)');
  // Height would be (630-540)/1440 * totalHeight = 90/1440 * 1440 = 90px (at 60px/hr)
  // That's 1.5 * 60 = 90px - correct
}

// Test 8: Event ending at 24:00 (1440 minutes)
{
  const result = computeDayLayout([
    { id: 1, title: 'A', minuteStart: 1380, minuteEnd: 1440 }  // 23:00-24:00
  ]);
  assert(result[0].minuteEnd === 1440, 'Event at 24:00 ends at 1440');
}

console.log('\nAll layout tests passed!');
"}

