/* Reset & Base */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

:root {
  --hour-height: 60px;
  --gutter-width: 60px;
  --header-height: 50px;
  --total-hours: 24;
  --grid-height: calc(var(--hour-height) * var(--total-hours));
  --border-color: #ddd;
  --today-bg: #e8f0fe;
  --event-bg: #4285f4;
  --event-text: #fff;
  --event-border: #3367d6;
}

html, body {
  height: 100%;
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  font-size: 14px;
  color: #333;
  background: #fafafa;
}

#app {
  display: flex;
  flex-direction: column;
  height: 100vh;
}

/* Header */
#calendar-header {
  display: flex;
  align-items: center;
  padding: 12px 16px;
  background: #fff;
  border-bottom: 1px solid var(--border-color);
  gap: 16px;
  flex-shrink: 0;
}

.nav-controls {
  display: flex;
  gap: 4px;
}

.nav-controls button {
  padding: 6px 14px;
  border: 1px solid var(--border-color);
  background: #fff;
  cursor: pointer;
  border-radius: 4px;
  font-size: 13px;
  transition: background 0.15s;
}

.nav-controls button:hover {
  background: #f0f0f0;
}

#week-title {
  font-size: 18px;
  font-weight: 600;
}

/* Calendar Container */
#calendar-container {
  flex: 1;
  overflow-y: auto;
  overflow-x: hidden;
  position: relative;
  display: grid;
  grid-template-columns: var(--gutter-width) 1fr;
  grid-template-rows: var(--header-height) 1fr;
}

/* Day Headers */
#day-headers {
  grid-column: 2;
  grid-row: 1;
  display: grid;
  grid-template-columns: repeat(7, 1fr);
  border-bottom: 1px solid var(--border-color);
  position: sticky;
  top: 0;
  z-index: 10;
  background: #fff;
}

.day-header {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 4px;
  border-left: 1px solid var(--border-color);
  font-size: 12px;
}

.day-header.today {
  background: var(--today-bg);
}

.day-header .day-name {
  text-transform: uppercase;
  color: #70757a;
  font-size: 11px;
  font-weight: 600;
}

.day-header .day-number {
  font-size: 22px;
  font-weight: 500;
  line-height: 1.2;
}

.day-header.today .day-number {
  background: var(--event-bg);
  color: #fff;
  border-radius: 50%;
  width: 32px;
  height: 32px;
  display: flex;
  align-items: center;
  justify-content: center;
}

/* Time Gutter - header spacer */
#time-gutter {
  grid-column: 1;
  grid-row: 1 / 3;
  position: sticky;
  top: 0;
  z-index: 11;
  background: #fff;
}

/* Time labels in gutter */
.time-label {
  position: absolute;
  right: 8px;
  font-size: 11px;
  color: #70757a;
  line-height: 1;
  transform: translateY(-50%);
  pointer-events: none;
}

/* Week Grid */
#week-grid {
  grid-column: 2;
  grid-row: 2;
  display: grid;
  grid-template-columns: repeat(7, 1fr);
  position: relative;
  height: var(--grid-height);
}

.day-column {
  position: relative;
  border-left: 1px solid var(--border-color);
}

.day-column.today {
  background: var(--today-bg);
}

/* Hour lines */
.hour-line {
  position: absolute;
  left: 0;
  right: 0;
  border-top: 1px solid var(--border-color);
  height: 0;
  pointer-events: none;
}

/* Half-hour lines */
.half-hour-line {
  position: absolute;
  left: 0;
  right: 0;
  border-top: 1px dotted #eee;
  height: 0;
  pointer-events: none;
}

/* Event blocks */
.event-block {
  position: absolute;
  background: var(--event-bg);
  color: var(--event-text);
  border: 1px solid var(--event-border);
  border-radius: 4px;
  padding: 2px 4px;
  font-size: 11px;
  overflow: hidden;
  cursor: pointer;
  z-index: 5;
  transition: filter 0.15s;
  line-height: 1.3;
}

.event-block:hover {
  filter: brightness(0.9);
  z-index: 6;
}

.event-block .event-title {
  font-weight: 600;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.event-block .event-time {
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  font-size: 10px;
  opacity: 0.9;
}

/* Modal */
.modal-overlay {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: rgba(0, 0, 0, 0.4);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 100;
}

.modal-overlay.hidden {
  display: none;
}

.modal {
  background: #fff;
  border-radius: 8px;
  padding: 24px;
  width: 400px;
  max-width: 90vw;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.15);
}

.modal h2 {
  margin-bottom: 16px;
  font-size: 18px;
}

.form-group {
  margin-bottom: 12px;
}

.form-group label {
  display: block;
  margin-bottom: 4px;
  font-size: 13px;
  font-weight: 500;
  color: #555;
}

.form-group input {
  width: 100%;
  padding: 8px 10px;
  border: 1px solid var(--border-color);
  border-radius: 4px;
  font-size: 14px;
}

.form-group input:focus {
  outline: none;
  border-color: var(--event-bg);
  box-shadow: 0 0 0 2px rgba(66, 133, 244, 0.2);
}

.form-error {
  color: #d93025;
  font-size: 13px;
  margin-bottom: 12px;
  padding: 6px 10px;
  background: #fce8e6;
  border-radius: 4px;
}

.form-error.hidden {
  display: none;
}

.form-actions {
